// Golden master of the current HTTP behaviour. Downstream pricing is an in-process fake.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'

let n = 0
async function start(prices = {}) {
  // fresh module instance per test: the service keeps orders and ids in module state
  const { createApp } = await import(`../src/app.mjs?fresh=${n++}`)
  const calls = []
  const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  const call = async (method, path, body, raw) => {
    const res = await fetch(base + path, { method, body: raw ?? (body === undefined ? undefined : JSON.stringify(body)) })
    return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
  }
  return { call, calls, close: () => server.close() }
}
const withApp = (prices, fn) => async () => { const a = await start(prices); try { await fn(a) } finally { a.close() } }

test('POST /orders 201 creates order, sums price*qty, ids start at "1"', withApp({ a: 10, b: 5 }, async ({ call, calls }) => {
  const r = await call('POST', '/orders', { items: [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }] })
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, { id: '1', items: [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }], total: 25 })
  assert.deepEqual(calls, ['a', 'b'])
  assert.equal((await call('POST', '/orders', { items: [{ sku: 'a', qty: 1 }] })).body.id, '2')
}))

test('POST /orders total of exactly 100 gets no discount', withApp({ a: 100 }, async ({ call }) => {
  assert.equal((await call('POST', '/orders', { items: [{ sku: 'a', qty: 1 }] })).body.total, 100)
}))

test('POST /orders total above 100 gets 10% off, then floored', withApp({ a: 101 }, async ({ call }) => {
  assert.equal((await call('POST', '/orders', { items: [{ sku: 'a', qty: 1 }] })).body.total, 90) // 90.9
}))

test('POST /orders total is floored, not rounded', withApp({ a: 1.5 }, async ({ call }) => {
  assert.equal((await call('POST', '/orders', { items: [{ sku: 'a', qty: 3 }] })).body.total, 4) // 4.5
}))

test('POST /orders missing qty gives null total', withApp({ a: 10 }, async ({ call }) => {
  // CHARACTERIZATION: current behaviour may be unintended — qty undefined makes total NaN, serialized as null, still 201
  const r = await call('POST', '/orders', { items: [{ sku: 'a' }] })
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
}))

for (const [name, body, raw] of [
  ['empty items', { items: [] }],
  ['missing items', {}],
  ['items not an array', { items: 'x' }],
  ['empty body', undefined],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, withApp({}, async ({ call, calls }) => {
    const r = await call('POST', '/orders', body, raw)
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
    assert.deepEqual(calls, [])
  }))
}

test('POST /orders 400 does not consume an id', withApp({ a: 1 }, async ({ call }) => {
  await call('POST', '/orders', { items: [] })
  assert.equal((await call('POST', '/orders', { items: [{ sku: 'a', qty: 1 }] })).body.id, '1')
}))

test('GET /orders/:id 200 returns the stored order', withApp({ a: 10 }, async ({ call }) => {
  await call('POST', '/orders', { items: [{ sku: 'a', qty: 2 }] })
  const r = await call('GET', '/orders/1')
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, { id: '1', items: [{ sku: 'a', qty: 2 }], total: 20 })
}))

test('GET /orders/:id ignores the query string', withApp({ a: 10 }, async ({ call }) => {
  await call('POST', '/orders', { items: [{ sku: 'a', qty: 1 }] })
  assert.equal((await call('GET', '/orders/1?x=y')).body.id, '1')
}))

test('GET /orders/:id unknown id answers 200 with error body', withApp({}, async ({ call }) => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await call('GET', '/orders/999')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
}))

for (const [method, path] of [
  ['GET', '/orders'], ['GET', '/'], ['GET', '/orders/'], ['GET', '/orders/1/x'],
  ['POST', '/orders/1'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/nope'],
]) {
  test(`${method} ${path} 404 no route`, withApp({}, async ({ call }) => {
    const r = await call(method, path)
    assert.equal(r.status, 404)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'no route' })
  }))
}
